SQL_DOC.P_SQL:
SELECT NVL(PODT.PLANT,'SDSM') AS PLANT ,IVHD.LEGACY_IV_SERIAL AS DLVY_NO ,PODT.LEGACY_PO_NO AS PO_NO ,PODT.LEGACY_PO_SEQ AS PO_LNNO ,IVDT.STATUS AS STATUS ,IVDT.INVOICE_DATE AS DLVY_DUE_DATE ,PODT.UNIT_PRICE AS PRCH_UNT_PR ,IVDT.INV_QTY AS DLVY_DUE_QTY ,PODT.UNIT_PRICE*IVDT.INV_QTY AS DLVY_AMT ,SUBSTRB(PODT.REF_PR_NO,1,INSTRB(PODT.REF_PR_NO,'-',1,1)-1) AS POR_NO ,SUBSTRB(PODT.REF_PR_NO,INSTRB(PODT.REF_PR_NO,'-',1,1)+1,5) AS POR_LNNO ,'' AS REMARK ,TO_CHAR(SYSDATE,'YYYYMMDD') AS IF_DATE ,'N' AS IF_FLAG FROM ICOMIVDT IVDT, ICOMIVHD IVHD, ICOMPODT PODT WHERE IVDT.BUYER = '$G_RS.BUYER$' AND IVDT.INV_NO = '$G_RS.INV_NO$' AND IVDT.INV_SEQ= '$G_RS.INV_SEQ$' AND IVDT.BUYER = IVHD.BUYER AND IVDT.INV_NO= IVHD.INV_NO AND IVDT.BUYER = PODT.BUYER AND IVDT.PO_NO = PODT.PO_NO AND IVDT.PO_SEQ= PODT.PO_SEQ UNION ALL SELECT NVL(PODT.PLANT,'SDSM') AS PLANT ,IVDT.LEGACY_IV_SERIAL AS DLVY_NO ,PODT.LEGACY_PO_NO AS PO_NO ,PODT.LEGACY_PO_SEQ AS PO_LNNO ,IVDT.STATUS AS STATUS ,IVDT.INV_DATE AS DLVY_DUE_DATE ,PODT.UNIT_PRICE AS PRCH_UNT_PR ,IVDT.INV_QTY AS DLVY_DUE_QTY ,PODT.UNIT_PRICE*IVDT.INV_QTY AS DLVY_AMT ,SUBSTRB(PODT.REF_PR_NO,1,INSTRB(PODT.REF_PR_NO,'-',1,1)-1) AS POR_NO ,SUBSTRB(PODT.REF_PR_NO,INSTRB(PODT.REF_PR_NO,'-',1,1)+1,5) AS POR_LNNO ,'' AS REMARK ,TO_CHAR(SYSDATE,'YYYYMMDD') AS IF_DATE ,'N' AS IF_FLAG FROM WMSIVDT IVDT, ICOMPODT PODT WHERE IVDT.BUYER = '$G_RS.BUYER$' AND IVDT.INV_NO = '$G_RS.INV_NO$' AND IVDT.INV_SEQ= '$G_RS.INV_SEQ$' AND IVDT.BUYER = PODT.BUYER AND IVDT.PO_NO = PODT.PO_NO AND IVDT.PO_SEQ= PODT.PO_SEQ ORDER BY DLVY_NO, PO_NO, PO_LNNO
DECLARE BEGIN IF '$G_RS.PROCESS_TYPE$' = '0' THEN UPDATE ICOMIVDT SET SND_CHK = 'Y' , SND_DATM= SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND INV_SEQ= '$G_RS.INV_SEQ$'; ELSE UPDATE WMSIVDT SET SND_CHK = 'Y' , SND_DATM= SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND INV_SEQ= '$G_RS.INV_SEQ$'; END IF; END;
DECLARE BEGIN IF '$G_RS.PROCESS_TYPE$' = '0' THEN UPDATE ICOMIVDT SET SND_CHK = 'E' , SND_DATM= SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND INV_SEQ= '$G_RS.INV_SEQ$'; ELSE UPDATE WMSIVDT SET SND_CHK = 'E' , SND_DATM= SYSDATE WHERE BUYER = '$G_RS.BUYER$' AND INV_NO = '$G_RS.INV_NO$' AND INV_SEQ= '$G_RS.INV_SEQ$'; END IF; END;
